-- Completa metadatos genéricos del ajuste autorizado, sin cambiar valores, nombres ni relaciones.
ALTER TABLE `configuracion_bbdd` MODIFY COLUMN `code` VARCHAR(20) NOT NULL COMMENT 'Código único y legible de presentación de esta configuración, generado por el servicio. No sustituye la PK interna ni el UUID público y no identifica ninguna operación de negocio.',
  MODIFY COLUMN `alias` VARCHAR(200) NOT NULL COMMENT 'Nombre de presentación de la configuración para administradores autorizados. No participa en la autenticación ni en la construcción de consultas; los consumidores muestran este alias sin recibir las credenciales.',
  MODIFY COLUMN `version` INT UNSIGNED NOT NULL DEFAULT 1 COMMENT 'Versión incremental para concurrencia optimista. Toda modificación desde la interfaz exige la versión vigente y la incrementa; no representa una prueba exitosa ni la versión del servidor externo.',
  MODIFY COLUMN `fechacrea` TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Instante UTC de creación de la configuración con precisión de milisegundos. Es metadato administrativo local y no representa fechas de los datos externos ni el tiempo de una prueba de conexión.',
  MODIFY COLUMN `idusuariomod` INT NOT NULL COMMENT 'Usuario autenticado responsable de la última modificación administrativa. Lo asigna el servicio desde la sesión junto con la versión y fecha de cambio; no se acepta del formulario.',
  MODIFY COLUMN `fechamod` TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP(3) COMMENT 'Instante UTC de la última modificación administrativa, actualizado explícitamente por el servicio con precisión de milisegundos. No tiene ON UPDATE y no almacena tiempos de diagnóstico ni funciona como cursor remoto.',
  MODIFY COLUMN `estado` TINYINT NOT NULL DEFAULT 1 COMMENT 'Vigencia lógica del proyecto: 1 ACTIVO y 2 ELIMINADO. No implica borrado físico ni acredita conectividad. Habilitado controla la disponibilidad para consumidores de forma independiente; se preservan credenciales y referencias.';
